inline auto fold15_log2_3(T x) -> T
{
    auto ei = ieee_int<T>{0};
    auto m = split_exponent(x, ei);
    auto e = static_cast<T>(ei);
    const auto big = m >= T(1.5);
    m = big ? m * T(0.5) : m;
    e = big ? e + T(1) : e;
    const auto u = m - T(1);
    auto p = T(0.39549597970872297);
    p = p * u + T(-0.742734067083134);
    p = p * u + T(1.4455779696039384);
    return e + u * p;
}

