/// tanh(x) ~ x * P(x^2) on [-2.15, 2.15], input clamped there; degree 5.
template<typename T>
inline auto clamp_tanh_5(T x) -> T
{
    const auto xc = std::fmin(std::fmax(x, T(-2.1500000000000004)), T(2.1500000000000004));
    const auto x2 = xc * xc;
    auto p = T(0.023964727456805893);
    p = p * x2 + T(-0.22157112178111257);
    p = p * x2 + T(0.9778702903652505);
    return xc * p;
}

