/// tanh(x) ~ s / sqrt(1 + s^2), s = x * R(x^2) ~ sinh x, degree 3, x clamped to ±9.
/// tanh rounds to 1 in float past ~9.01, so the clamp costs nothing and s * s can't overflow.
template<typename T>
inline auto sigmoid_cheb_tanh_3(T x) -> T
{
    const auto xc = std::fmin(std::fmax(x, T(-9.0)), T(9.0));
    const auto x2 = xc * xc;
    auto r = T(0.22623756005259124);
    r = r * x2 + T(1.0);
    const auto s = xc * r;
    return s / std::sqrt(s * s + T(1));
}

